package gads

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/ctrlo/gads-go/internal/perltest"
)

// TestEncodeJSONGolden checks EncodeJSON against JSON::PP->canonical, the
// encoder of the pages and the API (generated by
// conformance/perl/gen_json_golden.pl)
func TestEncodeJSONGolden(t *testing.T) {
	data, err := os.ReadFile("../perljson/testdata/golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var g struct {
		Cases []struct {
			In      map[string]any `json:"in"`
			Compact string         `json:"compact"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatal(err)
	}
	for _, c := range g.Cases {
		v, err := perltest.Build(c.In)
		if err != nil {
			t.Fatal(err)
		}
		if got := EncodeJSON(v); got != c.Compact {
			t.Errorf("EncodeJSON(%v) = %s, Perl %s", c.In, got, c.Compact)
		}
	}
}
